def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    c=Counter(v for r in g for v in r)
    bg=c.most_common(1)[0][0]
    # accent = minority color forming isolated single cells (count small, not appearing as big structure)
    accent=[k for k,v in c.items() if k!=bg]
    a=accent[0]
    o=[[v if v==a else bg for v in r] for r in g]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v==a:
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        if 0<=i+di<H and 0<=j+dj<W and not (di==0 and dj==0):
                            o[i+di][j+dj]=1
    return o
